//! Golden-image tests. Each `tests/golden/NAME.t` is a tiny script:
//!
//! ```text
//! canvas W H
//! fd 4
//! rt 90
//! ...
//! ```
//!
//! run on a fresh turtle over a `W x H` bitmap; the resulting picture (one text
//! row per canvas row, `.` for colour 0 and a hex digit for any other palette
//! index) must equal `tests/golden/NAME.img`. The expected pictures are worked
//! out by hand from the rules in `LOGO.md`, never generated by the code.
//!
//! Commands: `fd n`, `bk n`, `lt n`, `rt n`, `pu`, `pd`, `home`, `cs`, `clean`,
//! `setxy x y`, `seth n`, `setpc n`, `ht`, `st`, `fill`.

use std::fs;
use std::path::Path;
use turtle::{Bitmap, Turtle};

fn run(script: &str) -> String {
    let mut lines = script.lines().filter(|l| !l.trim().is_empty());
    let header: Vec<&str> = lines
        .next()
        .expect("canvas line")
        .split_whitespace()
        .collect();
    assert_eq!(header[0], "canvas", "first line must be `canvas W H`");
    let mut canvas = Bitmap::new(header[1].parse().unwrap(), header[2].parse().unwrap());
    let mut turtle = Turtle::new();
    for line in lines {
        let words: Vec<&str> = line.split_whitespace().collect();
        let num = |i: usize| -> f64 { words[i].parse().unwrap() };
        match words[0] {
            "fd" => turtle.forward(&mut canvas, num(1)),
            "bk" => turtle.back(&mut canvas, num(1)),
            "lt" => turtle.left(&mut canvas, num(1)),
            "rt" => turtle.right(&mut canvas, num(1)),
            "pu" => turtle.pen_up(),
            "pd" => turtle.pen_down(),
            "home" => turtle.home(&mut canvas),
            "cs" => turtle.clear_screen(&mut canvas),
            "clean" => turtle.clean(&mut canvas),
            "setxy" => turtle.set_xy(&mut canvas, num(1), num(2)),
            "seth" => turtle.set_heading(&mut canvas, num(1)),
            "setpc" => turtle.set_pen_color(num(1) as u8),
            "ht" => turtle.hide(&mut canvas),
            "st" => turtle.show(&mut canvas),
            "fill" => turtle.fill(&mut canvas),
            other => panic!("unknown command {other:?}"),
        }
    }
    canvas.to_ascii()
}

#[test]
fn golden_images() {
    let dir = Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/golden");
    let mut cases: Vec<_> = fs::read_dir(&dir)
        .unwrap()
        .filter_map(Result::ok)
        .map(|e| e.path())
        .filter(|p| p.extension().is_some_and(|x| x == "t"))
        .collect();
    cases.sort();
    assert!(!cases.is_empty());
    let mut failures = Vec::new();
    for case in &cases {
        let got = run(&fs::read_to_string(case).unwrap());
        let want = fs::read_to_string(case.with_extension("img"))
            .unwrap_or_else(|_| panic!("missing {}", case.with_extension("img").display()));
        if got != want {
            failures.push(format!(
                "--- {} ---\nexpected:\n{want}got:\n{got}",
                case.display()
            ));
        }
    }
    assert!(failures.is_empty(), "{}", failures.join("\n"));
}
